<template>
  <section class="grid grid-cols-2 gap-6">
    <PageTitle title="Emergency Details" class="col-span-2" />
    <div class="col-span-2 flex flex-wrap justify-between items-center gap-4">
      <GoBackButton subject="emergencies" :fallback-to="{ name: 'emergencies' }" />
    </div>
    <AppLoader v-if="isLoading" class="col-span-2" subject="emergency details" />
    <AppError v-else-if="error" :error="error" title="Failed to load emergency details" class="col-span-2" />
    <AppEmpty v-else-if="!emergency" class="col-span-2" subject="emergency details" />
    <Card v-else class="grid col-span-2">
      <CardContent class="flex flex-col gap-4">
        <div class="grid grid-cols-1 sm:grid-cols-2 gap-4">
          <LabeledEntityDate label="Timestamp" :date="emergency.timestamp" />
          <LabeledEntityUser v-if="isAdminOrManager" :user-id="emergency.user_id" />
          <LabeledEntityProject label="Project" :project-id="emergency.project_id" />
          <LabeledEntityWorkShift label="Work Shift" :work-shift-id="emergency.work_shift_id" />
          <Separator class="col-span-full" />
          <LabeledValueIcon label="Location" :icon="MapPinIcon" content-class="w-full" class="col-span-full">
            <GoogleMap
              v-if="emergency.gps_point"
              :api-key="String(useRuntimeConfig().public.googleMapApiKey) || undefined"
              :center="{ lat: emergency.gps_point.latitude, lng: emergency.gps_point.longitude }"
              :zoom="16"
              :clickable-icons="false"
              :fullscreen-control="false"
              style="width: 100%"
              class="h-[360px] rounded-md overflow-hidden"
            >
              <CustomMarker
                :options="{
                  position: { lat: emergency.gps_point.latitude, lng: emergency.gps_point.longitude },
                  anchorPoint: 'CENTER',
                }"
              >
                <div class="flex items-center justify-center rounded-full bg-destructive p-2 shadow-md">
                  <SirenIcon class="w-4 h-4 text-white" />
                </div>
              </CustomMarker>
            </GoogleMap>
            <p v-else class="text-sm text-muted-foreground">No GPS data</p>
          </LabeledValueIcon>
          <template v-if="isAdmin">
            <Separator class="col-span-full" />
            <LabeledValueIcon
              label="Detection Note"
              :icon="AudioLinesIcon"
              content-class="w-full"
              class="col-span-full"
            >
              <audio v-if="emergency.audio_url" controls class="w-full">
                <source :src="emergency.audio_url" />
              </audio>
              <p v-else class="text-sm text-muted-foreground">No note captured for this detection</p>
            </LabeledValueIcon>
          </template>
        </div>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import { GoogleMap, CustomMarker } from 'vue3-google-map';
import { SirenIcon, MapPinIcon, AudioLinesIcon } from 'lucide-vue-next';
import { getWakeWordEventDetails, type GetWakeWordEventDetailsResponse } from '~/client';

definePageMeta({
  roles: ['admin', 'manager', 'canvasser', 'subcontractor_canvasser'],
  backLabel: 'emergency',
});

useHead({
  title: 'Emergency Details',
});

const route = useRoute('emergencies-id');
const emergencyId = computed(() => route.params.id?.toString() || '');
const { isAdminOrManager, isAdmin } = useUserRole();

const {
  data: emergency,
  error,
  isLoading,
} = useQuery({
  key: () => ['emergency-details', emergencyId.value],
  query: (): Promise<GetWakeWordEventDetailsResponse> =>
    getWakeWordEventDetails({
      composable: '$fetch',
      path: { wake_word_event_id: emergencyId.value },
    }),
  staleTime: 0,
  enabled: computed(() => !!emergencyId.value && route.name === 'emergencies-id'),
});
</script>
